#include <cstdio>
#include <cstring>
#include <cmath>
#include <cstdlib>
#include <vector>
#include <string>
#include <algorithm>
#include <queue>
#include <stack>
#include <deque>
#include <map>
#include <set>
#include <unordered_map>
#include <unordered_set>
#include <functional>
#include <numeric>
#include <sstream>
#include <iostream>
using namespace std;
int main(){string s;int k;cin>>s>>k;
string t;
for(char c:s)if(c!='-')t+=toupper((unsigned char)c);
int n=t.size();int first=n%k;if(first==0)first=k;
string r=t.substr(0,first);
for(int i=first;i<n;i+=k)r+="-"+t.substr(i,k);
printf("%s\n",r.c_str());return 0;}

